/* MIR/27 1.0. Source text is always escaped. No questions are bundled in this public file. */
(()=>{'use strict';
const C=MIRCore,S=MIRStore,$=s=>document.querySelector(s),main=$('#main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tidy=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim().toLowerCase();
let bank=null,state=null,index=new Map(),ready=false,busy=false,currentSession=null,enteredKey='',enteredAt=0,importPayload=null,importing=false;
const WEB='https://mir-2027.vercel.app';const importNonce=new URLSearchParams(location.hash.slice(1)).get('import');
const filters={text:'',subject:'',year:'',status:'eligible',images:false,favorites:false,page:0};let readingFilter='',readingPage=0,atlasPage=0;
const navItems=[['today','Hoy'],['bank','Banco de preguntas'],['topics','Temas y lecturas'],['review','Mi repaso'],['atlas','Atlas visual'],['exams','Simulacros'],['progress','Mi progreso'],['library','Biblioteca y copias']];
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500);}
function badge(t,kind=''){return`<span class="badge ${kind}">${esc(t)}</span>`;}
function statusText(q){if(q.sourceDiscrepancy)return'Discrepancia entre fuentes';if(q.isAnnulled)return'Anulada según la fuente';if(q.imageRequired&&!q.images?.length&&!q.image)return'Falta imagen';if(!C.eligible(q))return'Revisión pendiente';return q.status==='variante_matematica'?'Ejercicio original':'Fuente histórica';}
function lookup(id){return index.get(id);}
function route(){return(location.hash||'#today').slice(1).split('?')[0];}
function go(view){if(location.hash==='#'+view)render();else location.hash=view;}
function heading(title,sub=''){return`<div class="page-heading"><div><p class="eyebrow">TU ENTRENAMIENTO MÉDICO PERSONAL</p><h1>${esc(title)}</h1>${sub?`<p class="muted">${esc(sub)}</p>`:''}</div></div>`;}
function shell(title,body,sub=''){main.innerHTML=heading(title,sub)+body;$('#nav').querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===route()));main.querySelectorAll('[data-media]').forEach(el=>observeImage(el));}
function button(action,text,cls='ghost',extra=''){return`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;}
function renderNav(){const allowed=ready&&!S.recovering;$('#nav').innerHTML=allowed?navItems.map(([id,name])=>`<button data-view="${id}" class="${route()===id?'active':''}">${name}</button>`).join(''):'';$('#logout').hidden=S.local||!S.user;$('#mode').textContent=S.local?'LOCAL · PRIVADO':'WEB · ACCESO PRIVADO';}
function applyPrefs(){document.documentElement.style.setProperty('--reader-scale',String(state?.preferences.fontScale||1));document.documentElement.classList.toggle('focus-mode',!!state?.preferences.focus);}
async function save(){if(!state)return;$('#save-label').textContent='Guardando…';try{const next=await S.saveState(state);state=C.merge(state,next);$('#save-label').textContent=S.local?'Guardado en este dispositivo':'Sincronizado';}catch(e){$('#save-label').textContent='Cambios pendientes de sincronizar';toast(e.message);}}
function refs(d){const list=d.references||[];if(!list.length)return`<p class="muted small">${d.origin?.includes('original')?'Elaboración original; no se atribuye a un examen oficial.':'La ficha no especifica una referencia de página.'}</p>`;return`<details class="sources"><summary>Fuentes y página exacta (${list.length})</summary>${list.map(r=>`<p><strong>${esc(r.title||r.id||'Documento')}</strong>${r.pdfPage?` · PDF p. ${esc(r.pdfPage)}${r.pdfPageEnd&&r.pdfPageEnd!==r.pdfPage?'–'+esc(r.pdfPageEnd):''}`:''}${r.printedPage?` · impresa p. ${esc(r.printedPage)}`:''}${r.yearLabel?` · rótulo ${esc(r.yearLabel)}`:''}<br><span class="muted small">${esc(r.file||'')}</span>${S.local&&r.file&&bank.sources.some(x=>x.id===r.id&&x.originalIncluded)?` <a href="./biblioteca_originales/${encodeURIComponent(r.file)}${r.pdfPage?'#page='+encodeURIComponent(r.pdfPage):''}" target="_blank" rel="noopener">Abrir original en el paquete local</a>`:''}</p>`).join('')}</details>`;}
function paragraph(t){return`<div class="source-text">${esc(t)}</div>`;}
function correction(q,a){const key=q.answer,keyText=Number.isInteger(key)?q.options[key]:'La fuente no aporta una clave puntuable';const sourceComments=q.sourceCommentaries?.length?q.sourceCommentaries:[{title:'Comentario del documento',text:q.commentary||q.explanation||'',pdfPage:q.references?.[0]?.pdfPage}];const isCorrect=a?.selected!=null&&a.selected===key;return`<section class="correction"><div class="correction-top">${badge(a?.selected==null?'Sin respuesta':isCorrect?'Acertada':'Para repasar',isCorrect?'good':'warn')}<h3>${q.origin?.includes('original')?'Resultado del ejercicio':'Respuesta que selecciona la fuente'}</h3></div><p class="answer-key">${esc(keyText)}</p>${q.sourceDiscrepancy?'<p class="notice warning">Las fuentes discrepan. Esta pregunta queda fuera de la puntuación ordinaria.</p>':''}<p class="muted small">Comentario histórico del material aportado. No equivale a una revisión clínica vigente ni a una predicción para 2027.</p>${sourceComments.map((x,i)=>`<details class="commentary" ${i===0?'open':''}><summary>${esc(x.title||'Comentario de la fuente')}${x.yearLabel?' · '+esc(x.yearLabel):''}${x.pdfPage?' · p. '+esc(x.pdfPage):''}</summary>${x.options&&Number.isInteger(x.answer)?`<p class="small muted">Clave en esta fuente: ${x.answer+1}. ${esc(x.options[x.answer])}</p>`:''}${paragraph(x.text)}</details>`).join('')}${q.elaboration?`<details><summary>Elaboración didáctica, separada de la fuente</summary>${paragraph(q.elaboration)}</details>`:''}${q.optionExplanations?.length?`<details><summary>Comentarios por opción disponibles</summary>${q.optionExplanations.map((x,i)=>`<p><strong>${esc(q.options[i]||'Opción')}:</strong> ${esc(x)}</p>`).join('')}</details>`:'<p class="muted small">El análisis de alternativas se conserva dentro del comentario cuando la fuente lo incluye; no se añaden explicaciones genéricas para rellenar.</p>'}${q.takeaway?`<p class="takeaway"><strong>Recordatorio didáctico:</strong> ${esc(q.takeaway)}</p>`:''}${refs(q)}</section>`;}
function figures(q){const ids=q.images||[];return`<div class="question-images">${ids.map(id=>`<figure><button class="image-button" data-action="zoom" data-id="${esc(id)}"><img data-media="${esc(id)}" alt="Imagen del documento, ampliar" loading="lazy"></button><figcaption>Imagen del material aportado · pulsa para ampliar</figcaption></figure>`).join('')}${!ids.length&&q.image&&/^data:image\/(png|jpeg|webp);base64,/.test(q.image)?`<img class="source-image" src="${esc(q.image)}" alt="Imagen del material aportado">`:''}</div>`;}
const imageObserver='IntersectionObserver'in window?new IntersectionObserver(es=>{for(const e of es)if(e.isIntersecting){imageObserver.unobserve(e.target);fillImage(e.target);}}, {rootMargin:'250px'}):null;
function observeImage(el){if(imageObserver)imageObserver.observe(el);else fillImage(el);}
async function fillImage(el){try{const m=await S.media(el.dataset.media);if(!el.isConnected)return;if(m?.data&&/^data:image\/(png|jpeg|webp);base64,/.test(m.data)){el.src=m.data;el.alt=m.alt||'Imagen del documento';}else{el.alt='Imagen no disponible: el banco privado aún no ha incorporado este recurso.';el.classList.add('image-error');}}catch{el.alt='No se pudo cargar la imagen. Reintenta cuando haya conexión.';el.classList.add('image-error');}}
async function zoom(id){const m=await S.media(id);if(!m?.data)return toast('Esta imagen no está incorporada en el banco de este dispositivo.');showDialog('Imagen del documento',`<img class="zoom-image" src="${esc(m.data)}" alt="${esc(m.alt||'Imagen de la fuente')}"><p class="muted small">${esc(m.alt||'')} · Conserva el contexto clínico de la pregunta al interpretarla.</p>`);}
function showDialog(title,body){const d=$('#dialog');d.innerHTML=`<div class="dialog-top"><h2>${esc(title)}</h2><button data-action="close-dialog" aria-label="Cerrar">×</button></div>${body}`;d.showModal();}
function start(items,options={}){if(!items.length)return toast('No hay preguntas válidas para este filtro.');const s=C.makeSession(bank,state,items,options);state.sessions[s.id]=s;state.activeSession=s.id;currentSession=s.id;save();go('session');}
function today(){const key=C.dayKey(new Date(),state.preferences.timezone),existing=state.sessions['daily-'+key],last=state.sessions[state.activeSession],n=bank.questions.filter(C.eligible).length,st=C.stats(state);shell('Hoy',`<section class="hero"><div><p class="eyebrow">POCO CADA DÍA, BIEN APRENDIDO</p><h2>${existing?.status==='complete'?'Tu sesión de hoy está completada':state.preferences.dailySize+' '+(state.preferences.dailyMode==='questions'?'preguntas':'actividades')+'. Un paso real.'}</h2><p>Preguntas del banco documental, comentario íntegro de la fuente y repaso de errores. Sin convertir un porcentaje histórico en una promesa para 2027.</p><div class="toolbar">${button('daily',existing?existing.status==='complete'?'Revisar la sesión':'Continuar mi sesión':'Empezar mi sesión','primary')}${last&&last.id!==existing?.id&&last.status==='active'?button('resume','Retomar bloque pendiente','light'):''}</div></div><div class="hero-number">${state.preferences.dailySize}<span>${state.preferences.dailyMode==='questions'?'preguntas de hoy':'actividades de hoy'}</span></div></section><div class="metrics"><div class="card"><strong class="metric">${n.toLocaleString('es-ES')}</strong><span>preguntas para practicar</span></div><div class="card"><strong class="metric">${st.unresolved}</strong><span>preguntas con último intento fallado</span></div><div class="card"><strong class="metric">${st.first.percent==null?'—':st.first.percent+'%'}</strong><span>aciertos en primer intento</span></div></div><div class="two-columns"><section class="card"><h2>Tu rutina</h2><p>Elige el formato. Los bloques extra son voluntarios.</p><label>Sesión diaria<select id="daily-mode"><option value="mixed" ${state.preferences.dailyMode==='mixed'?'selected':''}>Preguntas + tarjetas + lecturas</option><option value="questions" ${state.preferences.dailyMode==='questions'?'selected':''}>Solo preguntas</option></select></label><label class="spaced">Tamaño de la sesión<select id="daily-size">${[5,10,15,20,25,50].map(n=>`<option value="${n}" ${state.preferences.dailySize===n?'selected':''}>${n} actividades</option>`).join('')}</select></label><div class="toolbar spaced">${button('extra','+5 preguntas','ghost','data-count="5"')}${button('extra','+10','ghost','data-count="10"')}${button('extra','+25','ghost','data-count="25"')}</div><p class="small muted">La selección adaptativa es una regla de estudio, no un algoritmo validado para predecir tu puesto MIR.</p></section><section class="card"><h2>Contenido con procedencia</h2><p><b>${bank.readings.length}</b> lecturas · <b>${bank.flashcards.length}</b> tarjetas · <b>${bank.atlas.filter(x=>x.images?.length).length}</b> fichas visuales vinculadas.</p><p>Las preguntas anuladas, discrepantes o sin su imagen necesaria quedan apartadas del entrenamiento automático.</p>${button('navigate','Explorar el banco','primary','data-view="bank"')}</section></div>${S.local?'<p class="notice">Modo local: el banco está incluido en este archivo y el progreso se guarda en este navegador. No se sincroniza con otros dispositivos hasta conectar la copia privada con la web.</p>':''}`);$('#daily-size').onchange=e=>{state.preferences.dailySize=+e.target.value;save();today();toast('El nuevo tamaño se aplicará a la próxima sesión diaria.');};$('#daily-mode').onchange=e=>{state.preferences.dailyMode=e.target.value;save();today();toast('Preferencia guardada; una sesión ya iniciada no se modifica.');};}
function daily(){const key=C.dayKey(new Date(),state.preferences.timezone),id='daily-'+key;let s=state.sessions[id];if(!s){const items=C.selectDaily(bank,state,key,state.preferences.dailySize);if(!items.length)return toast('El banco no tiene actividades disponibles.');s=C.makeSession(bank,state,items,{id,kind:'daily',title:'Mi sesión · '+key});state.sessions[id]=s;}if(s.status==='complete')s.index=0;else state.activeSession=id;currentSession=id;save();go('session');}
function selectItems(list,count=10){return C.shuffled(list,Date.now()).slice(0,count).map(q=>({id:q.id,kind:'question'}));}
function bankView(){const subjects=[...new Set(bank.questions.map(x=>x.subject||'Sin clasificar'))].sort(),years=[...new Set(bank.questions.map(x=>x.year).filter(Boolean))].sort((a,b)=>b-a);shell('Banco de preguntas',`<section class="card filters"><label class="wide">Buscar en enunciados, temas y comentarios<input id="bank-search" type="search" placeholder="Ej.: disnea, sensibilidad, insuficiencia cardiaca…" value="${esc(filters.text)}"></label><label>Asignatura<select id="filter-subject"><option value="">Todas</option>${subjects.map(x=>`<option value="${esc(x)}" ${filters.subject===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Año según fuente<select id="filter-year"><option value="">Todos</option>${years.map(x=>`<option ${String(x)===filters.year?'selected':''}>${x}</option>`).join('')}</select></label><label>Estado<select id="filter-status"><option value="eligible" ${filters.status==='eligible'?'selected':''}>Para practicar</option><option value="pending" ${filters.status==='pending'?'selected':''}>Pendientes de revisión</option><option value="all" ${filters.status==='all'?'selected':''}>Todas</option></select></label><label class="check"><input id="filter-images" type="checkbox" ${filters.images?'checked':''}>Con imagen incorporada</label><label class="check"><input id="filter-favorites" type="checkbox" ${filters.favorites?'checked':''}>Mis favoritas</label></section><div id="bank-results"></div>`,'Busca el contenido, no solo el título del PDF.');$('#bank-search').oninput=e=>{filters.text=e.target.value;filters.page=0;clearTimeout(bankView.timer);bankView.timer=setTimeout(bankResults,140);};for(const [id,key] of [['filter-subject','subject'],['filter-year','year'],['filter-status','status'],['filter-images','images'],['filter-favorites','favorites']])$('#'+id).onchange=e=>{filters[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;filters.page=0;bankResults();};bankResults();}
function filteredQuestions(){const text=tidy(filters.text);return bank.questions.filter(q=>(filters.status==='all'||(filters.status==='eligible'?C.eligible(q):!C.eligible(q)))&&(!filters.subject||q.subject===filters.subject)&&(!filters.year||String(q.year)===filters.year)&&(!filters.images||q.images?.length||q.image)&&(!filters.favorites||state.marks[q.id]?.value)&&(!text||tidy(q.stem+' '+q.subject+' '+q.topic+' '+(q.commentary||'')+' '+(q.sourceCommentaries||[]).map(c=>c.text).join(' ')).includes(text)));}
function bankResults(){const list=filteredQuestions(),pages=Math.max(1,Math.ceil(list.length/20));filters.page=Math.max(0,Math.min(filters.page,pages-1));$('#bank-results').innerHTML=`<div class="results-bar"><p><strong>${list.length.toLocaleString('es-ES')}</strong> preguntas encontradas</p>${button('practice-filter','Practicar hasta 10','primary')}${button('print-filter','Imprimir selección (hasta 25)')}</div>${list.slice(filters.page*20,filters.page*20+20).map(q=>`<article class="card bank-row"><div class="row-meta">${badge(q.subject||'Sin clasificar')}${badge(q.year?'MIR según fuente · '+q.year:'Original')}${badge(statusText(q),C.eligible(q)?'':'warn')}${q.images?.length?badge('Con imagen'):''}</div><h3>${esc(q.stem)}</h3><p class="muted small">${esc(q.topic||'')} · ${q.references?.length||0} referencia(s)</p><div class="toolbar">${button('open-question',C.eligible(q)?'Responder y estudiar':'Examinar la fuente','primary',`data-id="${esc(q.id)}"`)}${button('favorite',state.marks[q.id]?.value?'★ Guardada':'☆ Guardar','ghost',`data-id="${esc(q.id)}"`)}</div></article>`).join('')||'<div class="empty">No hay resultados con estos filtros.</div>'}<div class="toolbar pagination">${button('bank-page','Anterior','ghost',`data-page="${filters.page-1}" ${filters.page===0?'disabled':''}`)}<span>Página ${filters.page+1} de ${pages}</span>${button('bank-page','Siguiente','ghost',`data-page="${filters.page+1}" ${filters.page+1>=pages?'disabled':''}`)}</div>`;}
function openQuestion(id){const q=lookup(id);if(!q)return;if(C.eligible(q))return start([{id,kind:'question'}],{title:'Estudio de una pregunta'});shell('Revisión documental',`<article class="card">${badge(statusText(q),'warn')}<h2>${esc(q.stem)}</h2>${figures(q)}<ol>${q.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ol><p class="notice warning">No se puntúa ni entra en la sesión automática. Motivos: ${esc((q.flags||[]).join(' · ')||statusText(q))}.</p>${correction(q,null)}${button('navigate','Volver al banco','ghost','data-view="bank"')}</article>`);}
function sessionView(){const s=state.sessions[currentSession||state.activeSession];if(!s)return go('today');currentSession=s.id;if(s.status==='active'&&s.deadline&&Date.now()>=s.deadline){C.finish(state,s,lookup);save();}if(s.status==='complete'&&s.mode==='exam')return resultView(s);const i=Math.min(s.index||0,s.items.length-1),item=s.items[i],q=item?.data||lookup(item?.id);if(!q)return shell('Contenido no disponible','<p class="notice warning">Esta sesión hace referencia a un contenido que no está cargado. El historial no se ha eliminado.</p>');const key=s.id+':'+i;if(key!==enteredKey){enteredKey=key;enteredAt=Date.now();}const a=s.answers[i]||{},exam=s.mode==='exam',finished=s.status==='complete',revealed=(a.submitted&&!exam)||finished;const answered=Object.values(s.answers).filter(x=>x.submitted).length;
let body=`<div class="session-bar"><span>Actividad <strong>${i+1}/${s.items.length}</strong> · ${esc(item.reason||'')}</span>${s.deadline&&s.status!=='complete'?'<strong id="countdown"></strong>':''}${button('session-print','Imprimir')}${s.status==='complete'&&s.mode!=='exam'?button('session-print-solutions','Imprimir explicaciones'):''}</div><progress max="${s.items.length}" value="${answered}"></progress>`;
if(item.kind==='question')body+=`<article class="card question-card"><div class="row-meta">${badge(q.subject||'Sin clasificar')}${badge(q.year?'Fuente · '+q.year:'Original')}${badge(exam&&!finished?'Examen · soluciones al entregar':statusText(q))}</div><p class="muted small">${esc(q.topic||'')}</p>${q.context?`<details class="notice" open><summary>Contexto que acompaña a esta pregunta</summary>${paragraph(q.context.stem)}${refs(q.context)}</details>`:''}<h2 class="stem">${esc(q.stem)}</h2>${figures(q)}<div class="options">${(item.order||q.options.map((_,j)=>j)).map((orig,pos)=>`<button class="option ${a.selected===orig?'selected':''} ${revealed&&orig===q.answer?'correct':''} ${revealed&&a.selected===orig&&orig!==q.answer?'wrong':''}" data-action="select-option" data-index="${orig}" ${(finished||a.submitted&&!exam)?'disabled':''}><span class="option-number">${pos+1}</span><span>${esc(q.options[orig])}</span></button>`).join('')}</div><div class="toolbar spaced"><label>Seguridad<select id="confidence" ${finished||a.submitted&&!exam?'disabled':''}><option value="unsure" ${a.confidence==='unsure'?'selected':''}>Dudaba</option><option value="sure" ${a.confidence==='sure'?'selected':''}>Estaba seguro</option><option value="guess" ${a.confidence==='guess'?'selected':''}>Al azar</option></select></label>${button('answer','Confirmar respuesta','primary',`${finished||a.submitted&&!exam?'disabled':''}`)}${button('blank','Dejar en blanco','ghost',`${finished||a.submitted&&!exam?'disabled':''}`)}</div>${revealed?correction(q,a):''}<div class="toolbar spaced">${button('favorite',state.marks[q.id]?.value?'★ Guardada':'☆ Guardar','ghost',`data-id="${esc(q.id)}"`)}${button('note','Mi nota','ghost',`data-id="${esc(q.id)}"`)}${button('report','Señalar problema','ghost',`data-id="${esc(q.id)}"`)}</div></article>`;
else if(item.kind==='flashcard')body+=`<article class="card"><p class="eyebrow">RECUPERACIÓN SIN OPCIONES</p><h2>${esc(q.front)}</h2><details class="commentary" ${a.submitted||finished?'open':''}><summary>Mostrar respuesta de la tarjeta</summary>${paragraph(q.back)}${refs(q)}</details><div class="toolbar spaced">${['again','hard','good'].map((rate,j)=>button('rate',['No lo recordaba','Me costó','Lo recordaba'][j],j===2?'primary':'ghost',`data-rating="${rate}" ${a.submitted||finished?'disabled':''}`)).join('')}</div></article>`;
else body+=`<article class="card"><p class="eyebrow">LECTURA DEL MATERIAL APORTADO</p><h2>${esc(q.title)}</h2><p class="notice small">Se conserva el contenido de la fuente, no se presenta como actualización clínica actual.</p>${(q.sections||[]).map(x=>`<section class="reading-section"><h3>${esc(x.title)}</h3>${paragraph(x.text)}</section>`).join('')}${refs(q)}${button('read-done','Lectura realizada','primary',`${a.submitted||finished?'disabled':''}`)}</article>`;
body+=`<div class="session-nav">${button('previous','← Anterior','ghost',i===0?'disabled':'')}${button('next',i===s.items.length-1?(finished?'Volver a Hoy':exam?'Entregar examen':'Terminar sesión'):'Siguiente →','primary')}${!finished&&exam?button('finish-exam','Entregar ahora','ghost'):''}${button('navigate','Pausar y volver a Hoy','ghost','data-view="today"')}</div>${exam&&!finished?`<details class="card"><summary>Navegador del examen · ${answered} confirmadas</summary><div class="question-grid">${s.items.map((_,j)=>`<button class="${s.answers[j]?.submitted?'answered':''} ${j===i?'current':''}" data-action="jump" data-index="${j}">${j+1}</button>`).join('')}</div></details>`:''}`;shell(s.title,body);tick();}
function activeS(){return state.sessions[currentSession||state.activeSession];}
async function submitAnswer(blank=false){const s=activeS();if(!s)return;const i=s.index||0,item=s.items[i];if(s.status==='complete'||item.kind!=='question')return;const selected=blank?null:s.answers[i]?.selected;if(!blank&&selected==null)return toast('Elige una opción o utiliza «Dejar en blanco».');C.answer(state,s,i,{selected,confidence:$('#confidence')?.value||'unsure',seconds:(Date.now()-enteredAt)/1000},lookup);await save();sessionView();}
async function next(){const s=activeS();if(!s)return;const i=s.index||0;if(s.status!=='complete'&&!s.answers[i]?.submitted){if(s.mode==='exam')C.answer(state,s,i,{selected:s.answers[i]?.selected??null,confidence:s.answers[i]?.confidence||'unsure',seconds:(Date.now()-enteredAt)/1000},lookup);else return toast('Registra la respuesta, deja la pregunta en blanco o marca la actividad.');}if(i>=s.items.length-1){if(s.status==='complete')return go('today');if(s.mode==='exam'&&!confirm('¿Entregar el examen? Las preguntas sin confirmar quedarán en blanco.'))return;C.finish(state,s,lookup);await save();if(s.mode==='exam')resultView(s);else{toast('Sesión completada y guardada.');go('today');}}else{s.index=i+1;s.updatedAt=Date.now();await save();sessionView();}}
function resultView(s){const st=C.score(s);shell('Resultado del simulacro',`<div class="metrics"><div class="card"><strong class="metric">${st.correct}</strong><span>correctas</span></div><div class="card"><strong class="metric">${st.wrong}</strong><span>incorrectas</span></div><div class="card"><strong class="metric">${st.blank}</strong><span>en blanco</span></div></div><section class="card"><h2>${st.net.toFixed(2).replace('.',',')} netas de entrenamiento</h2><p>Puntuación bruta: ${st.raw} (+3 por acierto, −1 por error). ${s.items.length>s.mainCount?'Las preguntas de reserva se corrigen, pero no se suman sin una sustitución.':''} No estima un puesto ni una nota oficial MIR 2027.</p><div class="toolbar">${button('session-print','Imprimir preguntas')}${button('session-print-solutions','Imprimir corrección')}${button('navigate','Mi progreso','primary','data-view="progress"')}</div></section>${s.items.map((item,i)=>{const q=item.data||lookup(item.id),a=s.answers[i]||{};if(!q||item.kind!=='question')return'';return`<details class="card"><summary><strong>${i+1}. ${a.selected==null?'—':a.selected===q.answer?'✓':'✗'} ${esc(q.subject||'')}${i>=s.mainCount?' · reserva':''}</strong></summary><h3>${esc(q.stem)}</h3>${figures(q)}<p>Tu respuesta: ${a.selected==null?'En blanco':esc(q.options[a.selected])}</p>${correction(q,a)}</details>`;}).join('')}`);}
function topics(){const groups={};for(const q of bank.questions.filter(C.eligible)){const k=q.subject||'Sin clasificar';(groups[k]??=[]).push(q);}shell('Temas y lecturas',`<section class="card"><label>Buscar una lectura o tema<input type="search" id="reading-search" value="${esc(readingFilter)}" placeholder="Busca un tema, asignatura o título"></label><div id="reading-results"></div></section><h2>Practicar por asignatura</h2><div class="cards-grid">${Object.entries(groups).sort((a,b)=>a[0].localeCompare(b[0],'es')).map(([name,items])=>`<section class="card"><h3>${esc(name)}</h3><p>${items.length} preguntas disponibles</p>${button('subject','Practicar hasta 10','primary',`data-subject="${esc(name)}"`)}</section>`).join('')}</div>`,'Lecturas de tus documentos y selección de sus comentarios, con referencias.');$('#reading-search').oninput=e=>{readingFilter=e.target.value;readingPage=0;readingResults();};readingResults();}
function readingResults(){const text=tidy(readingFilter),rs=bank.readings.filter(r=>!text||tidy(r.title+' '+r.subject+' '+r.topic+' '+(r.sections||[]).map(s=>s.text).join(' ')).includes(text));const pages=Math.max(1,Math.ceil(rs.length/40));readingPage=Math.max(0,Math.min(readingPage,pages-1));$('#reading-results').innerHTML=`<p class="small muted">${rs.length} lecturas · página ${readingPage+1} de ${pages}.</p><div class="reading-list">${rs.slice(readingPage*40,readingPage*40+40).map(r=>`<button class="reading-link" data-action="reading" data-id="${esc(r.id)}"><strong>${esc(r.title)}</strong><span>${esc(r.subject||'')} · ${r.minutes||'—'} min orientativos</span></button>`).join('')}</div><div class="toolbar pagination">${button('reading-page','Lecturas anteriores','ghost',`data-page="${readingPage-1}" ${readingPage===0?'disabled':''}`)}${button('reading-page','Más lecturas','ghost',`data-page="${readingPage+1}" ${readingPage+1>=pages?'disabled':''}`)}</div>`;}
function review(){const last=C.latest(state),errors=bank.questions.filter(q=>C.eligible(q)&&last.get(q.id)?.correct===false),due=bank.questions.filter(q=>C.eligible(q)&&state.schedule[q.id]?.dueAt<=Date.now()),fav=bank.questions.filter(q=>C.eligible(q)&&state.marks[q.id]?.value),st=C.stats(state);shell('Mi repaso',`<div class="cards-grid"><section class="card"><h2>${errors.length} errores pendientes</h2><p>Solo se mantiene el último intento de cada pregunta. Un error ya corregido no sigue apareciendo como pendiente.</p>${button('review-errors','Repasar hasta 10','primary',errors.length?'':'disabled')}</section><section class="card"><h2>${due.length} repasos vencidos</h2><p>Intervalos adaptados a la respuesta y a tu seguridad; son reglas de estudio transparentes.</p>${button('review-due','Repasar hasta 10','primary',due.length?'':'disabled')}</section><section class="card"><h2>${fav.length} favoritas</h2><p>Tu selección personal, independiente de la frecuencia histórica del examen.</p>${button('review-favorites','Practicar favoritas','primary',fav.length?'':'disabled')}</section></div><section class="card"><h2>${st.confidentErrors} errores con alta seguridad</h2><p>Estos errores reciben prioridad: conviene revisar el razonamiento, no memorizar la posición de la opción.</p></section><section class="card"><h2>Mis notas</h2>${Object.entries(state.notes).filter(([,n])=>typeof n==='string'?n:n?.text).slice(0,50).map(([id,n])=>`<article class="note"><strong>${esc(lookup(id)?.subject||'Nota')}</strong><p>${esc(typeof n==='string'?n:n.text)}</p>${button('open-question','Abrir pregunta','ghost',`data-id="${esc(id)}"`)}</article>`).join('')||'<p class="muted">Guarda una nota desde cualquier pregunta.</p>'}</section>`);}
function atlas(){const list=bank.atlas.filter(x=>x.images?.length||x.image),pages=Math.max(1,Math.ceil(list.length/12));atlasPage=Math.max(0,Math.min(atlasPage,pages-1));shell('Atlas visual',`<p class="notice">Las imágenes proceden del material aportado. No son imágenes clínicas generadas ni una interpretación diagnóstica independiente.</p><div class="cards-grid">${list.slice(atlasPage*12,atlasPage*12+12).map(a=>`<article class="card"><h3>${esc(a.title)}</h3>${figures(a)}${a.questionId?button('open-question','Resolver su pregunta','primary',`data-id="${esc(a.questionId)}"`):`<p>${esc(a.prompt||'')}</p>`}${refs(a)}</article>`).join('')||'<section class="card"><h2>Sin imágenes incorporadas en esta copia</h2><p>Una ficha sin imagen no se cuenta como atlas completo.</p></section>'}</div><div class="toolbar">${button('atlas-page','Anterior','ghost',`data-page="${atlasPage-1}" ${atlasPage===0?'disabled':''}`)}<span>${atlasPage+1} / ${pages} · ${list.length} fichas</span>${button('atlas-page','Siguiente','ghost',`data-page="${atlasPage+1}" ${atlasPage+1>=pages?'disabled':''}`)}</div>`);}
function exams(){const n=bank.questions.filter(C.eligible).length;const history=Object.values(state.sessions).filter(s=>s.mode==='exam').sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));shell('Simulacros',`<section class="card"><h2>Examen cronometrado</h2><p>Soluciones ocultas hasta entregar, navegación entre preguntas, respuestas en blanco y guardado al avanzar. El tiempo continúa si cierras el navegador.</p><div class="toolbar">${[25,50,100,210].map(x=>button('exam',x===210?'Largo · 200 + 10':x+' preguntas',x===25?'primary':'ghost',`data-count="${x}" ${n<x?'disabled':''}`)).join('')}</div><p class="muted small">El bloque 200 + 10 es un formato de entrenamiento, no el examen oficial de 2027. No se generan casos clínicos nuevos sin revisión.</p></section><section class="card"><h2>Variantes de cálculo</h2><p>Números regenerados con solución matemática. Se identifican como ejercicios originales y no como preguntas oficiales.</p>${button('numeric','Practicar 5 ejercicios de NNT','primary')}</section><section class="card"><h2>Historial</h2>${history.map(s=>`<div class="history-row"><div><strong>${esc(s.title)}</strong><p class="small muted">${esc(s.date)} · ${s.status==='complete'?'Terminado':'En curso'}</p></div>${button('open-session',s.status==='complete'?'Ver corrección':'Continuar','ghost',`data-id="${esc(s.id)}"`)}</div>`).join('')||'<p>Aún no hay simulacros guardados.</p>'}</section>`);}
function progress(){const st=C.stats(state),firsts=state.attempts.filter(x=>x.kind==='question'&&x.first&&!x.help),sure=firsts.filter(x=>x.confidence==='sure');shell('Mi progreso',`<div class="metrics"><section class="card"><strong class="metric">${st.first.total}</strong><span>primeros intentos sin ayuda</span><b>${st.first.percent??'—'}% aciertos</b></section><section class="card"><strong class="metric">${st.repeat.total}</strong><span>repeticiones</span><b>${st.repeat.percent??'—'}% aciertos</b></section><section class="card"><strong class="metric">${st.completed}</strong><span>sesiones completas</span></section></div><section class="card"><h2>Por asignatura · primeros intentos</h2>${Object.entries(st.subjects).map(([sub,p])=>`<div class="stat-line"><span>${esc(sub)}</span><b>${p.percent}% · ${p.correct}/${p.total}</b><progress value="${p.correct}" max="${p.total}"></progress></div>`).join('')||'<p>Tus resultados aparecerán después de responder.</p>'}</section><div class="two-columns"><section class="card"><h2>Confianza y errores</h2><p>${st.confidentErrors} preguntas con último error de alta seguridad.</p><p>Cuando respondiste «seguro» en un primer intento: <b>${sure.length?Math.round(sure.filter(x=>x.correct).length*100/sure.length)+'%':'—'}</b> de acierto (${sure.length} intentos).</p><p class="muted small">Con pocas respuestas, el porcentaje es inestable. No se convierte en pronóstico de nota MIR.</p></section><section class="card"><h2>Aprendizaje complementario</h2><p>${st.cards} tarjetas registradas · ${st.readings} lecturas registradas.</p>${button('export-progress','Exportar copia de progreso','primary')}</section></div><section class="card"><h2>Sesiones recientes</h2>${Object.values(state.sessions).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0)).slice(0,20).map(s=>`<div class="history-row"><span>${esc(s.title)} · ${s.status==='complete'?'completa':'en curso'}</span>${button('open-session','Abrir','ghost',`data-id="${esc(s.id)}"`)}</div>`).join('')}</section>`);}
function library(){const eligible=bank.questions.filter(C.eligible).length;let sources=bank.sources;const counts=new Map();for(const q of bank.questions)for(const r of q.references||[])counts.set(r.id,(counts.get(r.id)||0)+1);shell('Biblioteca y copias',`<div class="metrics"><section class="card"><strong class="metric">${bank.questions.length.toLocaleString('es-ES')}</strong><span>registros en esta copia</span></section><section class="card"><strong class="metric">${eligible.toLocaleString('es-ES')}</strong><span>preguntas para practicar</span></section><section class="card"><strong class="metric">${bank.questions.length-eligible}</strong><span>apartadas de la sesión automática</span></section></div><section class="card"><h2>Tu material, tus datos</h2><p>${S.local?'Esta es la edición local: el banco está incluido, sin cuenta nueva ni servicio de pago. El progreso es local a este navegador.':'Tu banco y tu progreso se guardan de forma privada. Entra con la misma cuenta en otro dispositivo para continuar.'}</p><div class="toolbar">${button('export-progress','Copiar progreso')}${button('import-progress','Recuperar/combinar progreso')}${S.local?button('bridge','Conectar este banco con mi web','primary'):S.role==='admin'?button('import-file','Importar banco privado','primary'):''}${S.local?button('export-bank','Exportar banco JSON'):''}</div><input id="file-input" type="file" accept=".json,application/json" hidden><p class="muted small">No se usa Google Drive. Una descarga debe guardarse en D: desde el navegador; la web no puede escribir silenciosamente en una unidad de tu ordenador.</p></section><section class="card"><h2>Documentos y cobertura real</h2>${sources.map(s=>`<details class="source-row"><summary><strong>${esc(s.title)}</strong> · ${counts.get(s.id)||0} referencias de preguntas</summary><p>${esc(s.file||s.file_name||'')} · ${s.pages||'—'} páginas en la ficha.</p><p>${esc(s.notes||'')}</p>${s.sha256?`<p class="small muted hash">SHA-256: ${esc(s.sha256)}</p>`:''}</details>`).join('')}</section><section class="card"><h2>Frecuencia observada, no predicción</h2><p>La priorización documental se presenta como recurrencia del corpus. No se inventa una probabilidad de salir en 2027.</p>${(bank.topicStats||[]).slice().sort((a,b)=>b.count-a.count).slice(0,20).map(t=>`<div class="history-row"><span>${esc(t.subject)} · ${esc(t.topic)}</span><b>${t.count} registros · ${t.distinctYears} años</b></div>`).join('')||'<p class="muted">Esta copia todavía no tiene un análisis del corpus completo.</p>'}</section><p class="muted small">Versión ${C.VERSION}. Tu recordatorio diario incluye el enlace de estudio; las preguntas y tu progreso permanecen dentro de tu espacio privado.</p>`);}
function render(){if(S.recovering)return resetPasswordView();if(route()==='recover')return recoveryView();if(!ready)return loginView();applyPrefs();const r=route();if(importPayload&&importNonce)return importView();({today,bank:bankView,topics,review,atlas,exams,progress,library,session:sessionView}[r]||today)();renderNav();}
function loginView(message=''){$('#save-label').textContent='Acceso privado';renderNav();shell('MIR/27',`<section class="auth-card"><div class="brand-large">MIR<span>/27</span></div><h2>Tu banco privado</h2><p>Entra con la cuenta que ya activaste. No hace falta crear otra.</p>${message?`<p class="notice warning">${esc(message)}</p>`:''}<form id="login"><label>Correo<input name="email" type="email" autocomplete="username" required></label><label>Contraseña<input name="password" type="password" autocomplete="current-password" required></label><button class="primary" type="submit">Entrar</button></form><p><a href="#recover">He olvidado mi contraseña</a></p><p class="small muted">Utiliza la misma cuenta en móvil y ordenador para conservar tu progreso.</p></section>`);$('#login').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await S.signIn(e.target.email.value,e.target.password.value);e.target.password.value='';await load();}catch(err){toast(err.message);b.disabled=false;}};}
function recoveryView(message=''){
 $('#save-label').textContent='Recuperar acceso';renderNav();
 shell('Recuperar contraseña',`<section class="auth-card"><h2>Vuelve a tu cuenta</h2><p>Escribe el correo con el que accedes a MIR/27. Te enviaremos un enlace para elegir una nueva contraseña.</p><p>Tu cuenta y tu progreso se conservan.</p><p id="recovery-message" class="notice" role="status" ${message?'':'hidden'}>${esc(message)}</p><form id="recover"><label>Correo<input name="email" type="email" autocomplete="username" required></label><button class="primary" type="submit">Enviar enlace de recuperación</button></form><p><a href="#today">Volver al acceso</a></p></section>`);
 $('#recover').onsubmit=async e=>{
  e.preventDefault();const form=e.target,b=form.querySelector('button'),notice=$('#recovery-message');b.disabled=true;notice.hidden=true;
  try{await S.requestPasswordReset(form.elements.namedItem('email').value);notice.textContent='Si el correo corresponde a tu cuenta, recibirás un enlace para cambiar la contraseña. Revisa también Spam y abre el correo más reciente.';notice.hidden=false;form.hidden=true;}
  catch(err){notice.textContent=err.status===429?'Se han solicitado varios enlaces. Espera unos minutos antes de intentarlo de nuevo.':err.message;notice.hidden=false;b.disabled=false;}
 };
}
function resetPasswordView(){
 $('#save-label').textContent='Elegir nueva contraseña';renderNav();
 shell('Nueva contraseña',`<section class="auth-card"><h2>Elige tu nueva contraseña</h2><p>Utiliza al menos 8 caracteres. Tu progreso seguirá asociado a la misma cuenta.</p><p id="password-message" class="notice warning" role="alert" hidden></p><form id="reset-password"><label>Nueva contraseña<input name="password" type="password" autocomplete="new-password" minlength="8" required></label><label>Repetir contraseña<input name="confirmation" type="password" autocomplete="new-password" minlength="8" required></label><button class="primary" type="submit">Guardar nueva contraseña</button></form><p>Después podrás entrar con la nueva contraseña.</p></section>`);
 $('#reset-password').onsubmit=async e=>{
  e.preventDefault();const form=e.target,password=form.elements.namedItem('password'),confirmation=form.elements.namedItem('confirmation'),b=form.querySelector('button'),notice=$('#password-message');
  if(password.value!==confirmation.value){notice.textContent='Las contraseñas no coinciden.';notice.hidden=false;return;}
  b.disabled=true;notice.hidden=true;
  try{await S.updatePassword(password.value);password.value='';confirmation.value='';await S.signOut();ready=false;bank=null;state=null;index.clear();history.replaceState(null,'','#today');loginView('Contraseña actualizada. Ya puedes entrar con la nueva.');}
  catch(err){notice.textContent=err.message;notice.hidden=false;b.disabled=false;}
 };
}
async function load(){$('#save-label').textContent='Cargando tu banco…';[bank,state]=await Promise.all([S.loadBank(),S.loadState()]);if(!bank?.questions)throw new Error('No se pudo leer el banco.');index=new Map([...bank.questions,...bank.readings,...bank.flashcards].map(x=>[x.id,x]));ready=true;$('#save-label').textContent=S.local?'Guardado en este dispositivo':'Sincronizado';render();}
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data)],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function chooseFile(kind){let input=$('#file-input');if(!input){input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.hidden=true;document.body.appendChild(input);}input.value='';input.onchange=async()=>{const f=input.files[0];if(!f)return;if(f.size>85000000)return toast('Archivo demasiado grande.');try{const data=JSON.parse(await f.text());if(kind==='progress'){if(!['mir2027.state.v1','mir2027.state.v2'].includes(data.schema)||!Array.isArray(data.attempts))throw new Error('No es una copia de progreso MIR/27.');if(!confirm('¿Combinar esta copia con tu progreso actual? Se conservarán los intentos distintos de ambas copias.'))return;state=C.merge(state,data);await save();toast('Progreso combinado.');render();}else{importPayload=data;importView();}}catch(e){toast('No se pudo leer: '+e.message);}};input.click();}
function importView(){if(!ready)return loginView('Entra para autorizar la incorporación del banco documental privado.');if(S.role!=='admin')return shell('Importar banco','<p class="notice warning">Se requiere la cuenta administradora del proyecto.</p>');const b=importPayload;if(b?.schema!=='mir2027.bank.v2'||!Array.isArray(b.questions))return shell('Importación no válida','<p>El archivo no tiene el formato esperado.</p>');shell('Autorizar incorporación privada',`<section class="card"><h2>${b.questions.length.toLocaleString('es-ES')} registros documentales</h2><p>Se enviarán desde este navegador a <strong>tu proyecto Supabase MIR/27</strong>. No se publicarán en GitHub ni se enviarán a Drive.</p><p>${b.sources?.length||0} fichas de fuente · ${Object.keys(b.media||{}).length} imágenes · ${b.readings?.length||0} lecturas.</p><p>Los comentarios conservan la redacción de las fuentes; no se etiquetan como una revisión clínica actual. Tu cuenta y tu progreso se mantienen.</p>${button('confirm-import',importing?'Importando…':'Autorizar e incorporar el banco','primary',importing?'disabled':'')}<div id="import-progress" aria-live="polite"></div><p class="muted small">La importación es por lotes y se puede repetir: actualiza por identificador sin duplicar esos registros.</p></section>`);}
async function doImport(){if(importing)return;importing=true;$('#main [data-action="confirm-import"]').disabled=true;try{const result=await S.importBank(importPayload,p=>{$('#import-progress').innerHTML=`<progress value="${p.processed}" max="${p.total}"></progress><p>${p.processed.toLocaleString('es-ES')} / ${p.total.toLocaleString('es-ES')} registros · ${esc(p.kind)} · ${p.rejected} apartados por validación.</p>`;});if(result.rejected.length){download('MIR27-incidencias-importacion.json',result);toast('Importación realizada con incidencias; se ha descargado el informe.');}else toast('Banco privado incorporado.');importPayload=null;importing=false;history.replaceState(null,'','#bank');await load();}catch(e){importing=false;toast('Importación interrumpida: '+e.message+' Puedes repetirla sin duplicar registros.');importView();}}
function bridge(){const nonce=C.uid().replace(/-/g,'')+C.uid().replace(/-/g,'');const popup=window.open(WEB+'/#import='+nonce,'mir27-import-'+nonce);if(!popup)return toast('Permite abrir la ventana de MIR/27 para autorizar la transferencia.');const listener=e=>{if(e.origin!==WEB||e.source!==popup||e.data?.type!=='MIR27_READY'||e.data?.nonce!==nonce)return;popup.postMessage({type:'MIR27_PRIVATE_BANK',nonce,bank:window.MIR_PRIVATE_BANK},WEB);};window.addEventListener('message',listener);setTimeout(()=>window.removeEventListener('message',listener),15*60000);toast('Se ha abierto tu web. Autoriza allí la incorporación privada. Tu contraseña no se comparte con este archivo.');}
if(importNonce&&/^[a-zA-Z0-9]{25,100}$/.test(importNonce)&&window.opener){window.addEventListener('message',e=>{if(e.source!==window.opener||!['null',WEB].includes(e.origin)||e.data?.type!=='MIR27_PRIVATE_BANK'||e.data?.nonce!==importNonce)return;importPayload=e.data.bank;if(ready)importView();});const signal=()=>window.opener?.postMessage({type:'MIR27_READY',nonce:importNonce},'*');signal();setTimeout(signal,1000);setTimeout(signal,3000);}
function tick(){if(!ready)return;const current=activeS(),el=$('#countdown');if(current?.status==='active'&&current.deadline&&el){const secs=Math.max(0,Math.ceil((current.deadline-Date.now())/1000));el.textContent=`${Math.floor(secs/60)}:${String(secs%60).padStart(2,'0')}`;}let changed=false;for(const s of Object.values(state.sessions)){if(s.status==='active'&&s.mode==='exam'&&s.deadline&&Date.now()>=s.deadline){C.finish(state,s,lookup);changed=true;if(route()==='session'&&current?.id===s.id)resultView(s);}}if(changed){save();toast('Tiempo agotado. El examen se ha entregado.');}}
async function printSession(s,solutions=false){if(!s)return toast('No hay una sesión para imprimir.');if(s.mode==='exam'&&s.status!=='complete'&&solutions)return toast('Entrega el examen antes de imprimir las soluciones.');await MIRPrint.open(s,lookup,id=>S.media(id),{solutions});}
main.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;if(busy&&!['select-option','navigate'].includes(a))return;try{const s=ready?activeS():null;switch(a){case'retry-load':await load();break;case'navigate':go(b.dataset.view);break;case'daily':daily();break;case'resume':currentSession=state.activeSession;go('session');break;case'extra':start(C.selectQuestions(bank,state,+b.dataset.count,Date.now()),{title:'Bloque extra de '+b.dataset.count});break;case'open-question':openQuestion(b.dataset.id);break;case'favorite':state.marks[b.dataset.id]={value:!state.marks[b.dataset.id]?.value,at:Date.now()};await save();b.textContent=state.marks[b.dataset.id].value?'★ Guardada':'☆ Guardar';break;case'bank-page':filters.page=+b.dataset.page;bankResults();window.scrollTo(0,0);break;case'practice-filter':start(selectItems(filteredQuestions().filter(C.eligible)),{title:'Práctica de mi selección'});break;case'print-filter':{const ps=C.makeSession(bank,state,selectItems(filteredQuestions().filter(C.eligible),25),{title:'Cuaderno de mi selección'});await printSession(ps,false);break;}case'select-option':if(s&&s.status!=='complete'){const i=s.index||0,old=s.answers[i]||{};if(old.submitted&&s.mode!=='exam')break;s.answers[i]={...old,selected:+b.dataset.index,submitted:false,confidence:$('#confidence')?.value||'unsure',at:Date.now()};if(s.mode==='exam')C.answer(state,s,i,{selected:+b.dataset.index,confidence:$('#confidence')?.value||'unsure',seconds:(Date.now()-enteredAt)/1000},lookup);s.updatedAt=Date.now();main.querySelectorAll('.option').forEach(x=>x.classList.toggle('selected',x===b));save();}break;case'answer':busy=true;await submitAnswer();break;case'blank':busy=true;await submitAnswer(true);break;case'next':busy=true;await next();break;case'previous':if(s){s.index=Math.max(0,(s.index||0)-1);s.updatedAt=Date.now();await save();sessionView();}break;case'jump':if(s){s.index=+b.dataset.index;s.updatedAt=Date.now();await save();sessionView();}break;case'rate':case'read-done':if(s){C.answer(state,s,s.index||0,{rating:a==='rate'?b.dataset.rating:'good',seconds:(Date.now()-enteredAt)/1000},lookup);await save();await next();}break;case'finish-exam':if(s&&confirm('¿Entregar el examen ahora? Las no confirmadas quedarán en blanco.')){C.finish(state,s,lookup);await save();resultView(s);}break;case'subject':start(selectItems(bank.questions.filter(q=>C.eligible(q)&&q.subject===b.dataset.subject)),{title:b.dataset.subject});break;case'reading':start([{kind:'reading',id:b.dataset.id}],{title:'Lectura del material'});break;case'review-errors':case'review-due':case'review-favorites':{const last=C.latest(state);const list=bank.questions.filter(q=>C.eligible(q)&&(a==='review-errors'?last.get(q.id)?.correct===false:a==='review-due'?state.schedule[q.id]?.dueAt<=Date.now():state.marks[q.id]?.value));start(selectItems(list),{title:'Mi repaso dirigido'});break;}case'reading-page':readingPage=+b.dataset.page;readingResults();break;case'atlas-page':atlasPage=+b.dataset.page;atlas();break;case'zoom':await zoom(b.dataset.id);break;case'exam':{const n=+b.dataset.count;start(selectItems(bank.questions.filter(C.eligible),n),{title:n===210?'Simulacro largo de entrenamiento':'Simulacro de '+n+' preguntas',kind:'exam',mode:'exam',minutes:n===210?270:Math.ceil(n*1.3),mainCount:n===210?200:n});break;}case'numeric':{const items=Array.from({length:5},(_,i)=>{const d=C.numeric(Date.now()+'-'+i);return{id:d.id,kind:'question',data:d};});start(items,{title:'NNT · variantes matemáticas'});break;}case'open-session':currentSession=b.dataset.id;if(state.sessions[currentSession].status==='complete')state.sessions[currentSession].index=0;else state.activeSession=currentSession;go('session');break;case'session-print':await printSession(s,false);break;case'session-print-solutions':await printSession(s,true);break;case'export-progress':download('MIR27-progreso-'+C.dayKey()+'.json',state);break;case'import-progress':chooseFile('progress');break;case'import-file':chooseFile('bank');break;case'export-bank':download('MIR27-banco-documental-privado.json',bank);break;case'confirm-import':await doImport();break;case'bridge':bridge();break;case'note':{const id=b.dataset.id,n=state.notes[id];showDialog('Mi nota',`<textarea id="note-text" rows="7">${esc(typeof n==='string'?n:n?.text||'')}</textarea><button class="primary" data-action="save-note" data-id="${esc(id)}">Guardar nota</button>`);break;}case'report':{const id=b.dataset.id;showDialog('Señalar problema',`<p>Se guardará en tu historial local/privado; no se envía a la editorial.</p><textarea id="report-text" rows="4" placeholder="Explica el problema de la fuente, imagen o pregunta"></textarea><button class="primary" data-action="save-report" data-id="${esc(id)}">Guardar incidencia</button>`);break;}}}catch(err){toast(err.message);}finally{busy=false;}});
$('#dialog').addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='close-dialog')return $('#dialog').close();if(b.dataset.action==='save-note'){state.notes[b.dataset.id]={text:$('#note-text').value,at:Date.now()};await save();$('#dialog').close();toast('Nota guardada.');}if(b.dataset.action==='save-report'){state.reports.push({id:C.uid(),itemId:b.dataset.id,text:$('#report-text').value,at:Date.now()});await save();$('#dialog').close();toast('Incidencia guardada.');}});
$('#nav').onclick=e=>{const b=e.target.closest('[data-view]');if(b)go(b.dataset.view);};$('#logout').onclick=async()=>{await S.signOut();ready=false;bank=null;state=null;index.clear();loginView();};$('#focus').onclick=()=>{if(state){state.preferences.focus=!state.preferences.focus;applyPrefs();save();}};$('#font-minus').onclick=()=>{if(state){state.preferences.fontScale=Math.max(.85,(state.preferences.fontScale||1)-.05);applyPrefs();save();}};$('#font-plus').onclick=()=>{if(state){state.preferences.fontScale=Math.min(1.4,(state.preferences.fontScale||1)+.05);applyPrefs();save();}};
window.addEventListener('hashchange',render);window.addEventListener('online',()=>{if(ready&&!S.local)save();});document.addEventListener('keydown',e=>{if(e.ctrlKey||e.altKey||e.metaKey||e.target.isContentEditable||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||$('#dialog').open)return;if(/^[1-5]$/.test(e.key)){const opt=main.querySelectorAll('.option:not(:disabled)')[+e.key-1];if(opt){opt.click();e.preventDefault();}}else if(e.key==='Enter'&&route()==='session'){const a=main.querySelector('[data-action="answer"]:not(:disabled)'),n=main.querySelector('[data-action="next"]');(a||n)?.click();e.preventDefault();}else if(e.key.toLowerCase()==='f'&&state){$('#focus').click();}else if(e.key==='Escape'&&state?.preferences.focus){state.preferences.focus=false;applyPrefs();save();}});
setInterval(tick,1000);$('#date-label').textContent=new Intl.DateTimeFormat('es-ES',{dateStyle:'long',timeZone:'Europe/Madrid'}).format(new Date());
(async()=>{try{const ctx=await S.init();if(ctx.recovery)return resetPasswordView();if(route()==='recover')return recoveryView();if(ctx.mode==='local'||ctx.user)await load();else loginView();}catch(e){if(route()==='recover')return recoveryView(e.message);if(S.local||S.user){shell('No se pudo cargar tu espacio',`<section class="card"><p>${esc(e.message)}</p>${button('retry-load','Volver a intentar','primary')}</section>`);}else loginView(e.message);}})();
})();
